     7	}
     8	
     9	const LEVEL_ORDER: Record<LogLevel, number> = {
    10	  debug: 10,
    11	  info: 20,
    12	  warn: 30,
    13	  error: 40
    14	};
    15	
    16	export function createLogger(minimumLevel: LogLevel): Logger {
    17	  return {
    18	    log(level, event, fields) {
    19	      if (LEVEL_ORDER[level] < LEVEL_ORDER[minimumLevel]) {
    20	        return;
    21	      }
    22	
    23	      const record = {
    24	        timestamp: new Date().toISOString(),
    25	        level,
    26	        event,
    27	        ...fields
    28	      };
    29	      const output = JSON.stringify(record);
    30	      if (level === "error") {
    31	        console.error(output);
    32	      } else {
    33	        console.log(output);
    34	      }
    35	    }
    36	  };
