    14	export class ApiClientError extends Error {
    15	  public constructor(
    16	    message: string,
    17	    public readonly code: ApiErrorCode | "NETWORK_ERROR" | "INVALID_RESPONSE",
    18	    public readonly status?: number,
    19	    public readonly fields?: Record<string, string[]>
    20	  ) {
    21	    super(message);
    22	    this.name = "ApiClientError";
    23	  }
    24	
    25	  public get isInvalidSession(): boolean {
    26	    return (
    27	      this.code === "AUTH_REQUIRED" ||
    28	      this.code === "AUTH_SESSION_EXPIRED" ||
    29	      this.code === "AUTH_SESSION_INVALID"
    30	    );
    31	  }
    32	}
    33	
    34	async function parseResponse<T>(
    35	  response: Response,
    36	  schema: z.ZodType<T>
    37	): Promise<T> {
    38	  let body: unknown;
    39	  try {
    40	    body = await response.json();
    41	  } catch {
    42	    throw new ApiClientError(
    43	      "服务器返回了无法识别的内容",
    44	      "INVALID_RESPONSE",
    45	      response.status
    46	    );
    47	  }
    48	
    49	  if (!response.ok) {
    50	    const error = apiErrorSchema.safeParse(body);
    51	    if (!error.success) {
    52	      throw new ApiClientError(
    53	        "服务器返回了无法识别的错误",
    54	        "INVALID_RESPONSE",
    55	        response.status
    56	      );
    57	    }
    58	    throw new ApiClientError(
    59	      error.data.error.message,
    60	      error.data.error.code,
    61	      response.status,
    62	      error.data.error.fields
    63	    );
    64	  }
    65	
    66	  const parsed = schema.safeParse(body);
    67	  if (!parsed.success) {
    68	    throw new ApiClientError(
    69	      "服务器数据格式不兼容，请稍后重试",
    70	      "INVALID_RESPONSE",
    71	      response.status
    72	    );
    73	  }
    74	  return parsed.data;
    75	}
